.panel { opacity: 1; transition: opacity 180ms ease; }
.panel[data-faded="true"] { opacity: .5; }
.notice { animation: appear 180ms ease; }
@keyframes appear { from { opacity: 0; } to { opacity: 1; } }

.card { transition: transform 180ms ease; }
@media (prefers-reduced-motion: reduce) {
  .card { transition: none; }
  html { scroll-behavior: auto; }
}

:root { color-scheme: light dark; --surface: light-dark(white, #18181b); }
.panel { background: var(--surface); border: 1px solid currentColor; }
@media (forced-colors: active) { .panel { border-color: CanvasText; } }
